WITH base AS (SELECT *, CEIL(unit_price) AS unit_price_whole FROM order_items WHERE (product_id IN (5, 15, 37) AND quantity BETWEEN 3 AND 6) OR order_id = 8), order_items_stats AS (SELECT CASE WHEN unit_price >= 340 THEN 'high' WHEN unit_price >= 100 THEN 'mid' ELSE 'low' END AS unit_price_bucket, CASE WHEN unit_price_whole >= 71 THEN 'high' WHEN unit_price_whole >= 17 THEN 'mid' ELSE 'low' END AS unit_price_whole_bucket, MAX(unit_price_whole) - MIN(unit_price_whole) AS unit_price_whole_range FROM base GROUP BY CASE WHEN unit_price >= 340 THEN 'high' WHEN unit_price >= 100 THEN 'mid' ELSE 'low' END, CASE WHEN unit_price_whole >= 71 THEN 'high' WHEN unit_price_whole >= 17 THEN 'mid' ELSE 'low' END) SELECT unit_price_bucket, unit_price_whole_bucket, unit_price_whole_range FROM order_items_stats ORDER BY unit_price_bucket;
